/** JSON response with the given status. */
export function json(status: number, value: unknown): Response {
  return Response.json(value, { status });
}

/** 429 Too Many Requests, with a Retry-After header in whole seconds. */
export function tooManyRequests(retryAfterMs: number, value: unknown): Response {
  const res = json(429, value);
  res.headers.set("retry-after", String(Math.ceil(retryAfterMs / 1000)));
  return res;
}
